use std::path::PathBuf;

use thiserror::Error;

#[derive(Debug, Error)]
pub enum CompactTerminalError {
    #[error("{0}")]
    InvalidRequest(String),

    #[error("cannot spawn command '{command}': {source}")]
    CannotSpawn {
        command: String,
        #[source]
        source: std::io::Error,
    },

    #[error("cannot create spill directory '{path}': {source}")]
    CannotCreateSpillDir {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },

    #[error("cannot write spill file '{path}': {source}")]
    CannotWriteSpillFile {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },

    #[error("cannot read spill file '{path}': {source}")]
    CannotReadSpillFile {
        path: PathBuf,
        #[source]
        source: std::io::Error,
    },

    #[error("command timed out after {timeout_secs} seconds")]
    Timeout { timeout_secs: u64 },

    #[error("task error: {0}")]
    TaskError(String),
}

use std::path::PathBuf;

use serde::{Deserialize, Serialize};

/// Request to run a shell command.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct RunRequest {
    /// The shell command to execute (passed to `sh -c`).
    pub command: String,

    /// Working directory for the command. Defaults to the current working dir.
    pub cwd: Option<PathBuf>,

    /// Maximum bytes to return inline. Outputs exceeding this are spilled to a
    /// transient file and summarised. Default: 4096.
    pub inline_limit: Option<usize>,

    /// Command timeout in seconds. Default: 60.
    pub timeout_secs: Option<u64>,

    /// Directory where spill files will be written. Defaults to system temp dir.
    pub spill_dir: Option<PathBuf>,
}

/// Request to read from a spill file.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ReadSpillRequest {
    /// Path to the transient spill file returned by a previous `run` call.
    pub spill_file: PathBuf,

    /// First line to read (1-based, inclusive). Defaults to 1.
    pub start: Option<usize>,

    /// Last line to read (1-based, inclusive). Defaults to start + 80.
    pub end: Option<usize>,

    /// Search pattern: returns matching line numbers (1-based) instead of content.
    pub grep: Option<String>,
}

use std::path::PathBuf;

use serde::{Deserialize, Serialize};

/// Result of a run command execution.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum RunResult {
    /// Short output returned inline.
    Inline {
        exit_code: i32,
        stdout: String,
        stderr: String,
        elapsed_ms: u128,
    },
    /// Long output spilled to a transient file.
    Spilled {
        exit_code: i32,
        /// First `inline_limit` bytes of stdout for quick scanning.
        stdout_preview: String,
        /// First `inline_limit` bytes of stderr.
        stderr_preview: String,
        /// Total bytes of combined output stored in the spill file.
        total_bytes: usize,
        /// Total lines in the spill file.
        total_lines: usize,
        /// Path to the transient file containing the full output.
        spill_file: PathBuf,
        elapsed_ms: u128,
        /// Suggested follow-up inspection commands.
        next_steps: Vec<String>,
    },
    /// Command timed out.
    TimedOut {
        timeout_secs: u64,
        /// Partial stdout captured before timeout.
        stdout_partial: String,
        spill_file: Option<PathBuf>,
    },
    /// Command could not be launched.
    LaunchError { message: String },
}

/// Result of reading a spill file.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ReadSpillResult {
    pub content: String,
}

